1	/**
2	 * Main Cloudflare Worker entry point for the Paperclip API.
3	 *
4	 * This file:
5	 *   1. Creates a Hono app and mounts route definitions.
6	 *   2. Implements the first-run setup gate (redirects to /setup until KV flag is set).
7	 *   3. Handles Cloudflare Queues message batches (plugin job fanout).
8	 *   4. Handles Cloudflare Cron Triggers (heartbeat sweep, budget checks, DB backup).
9	 *   5. Re-exports all Durable Object and Workflow classes so Wrangler can
10	 *      register them — they must be named exports from the Worker's main module.
11	 */
12	
13	import { Hono } from "hono";
14	import { createSetupApp } from "./setup.js";
15	import { bootCloudflare } from "../boot.js";
16	import { SidecarClient } from "../sidecar-client.js";
17	import { CfCompanySkillsService } from "../services/cf-company-skills.js";
18	import { CfAgentInstructionsService } from "../services/cf-agent-instructions.js";
19	
20	// createHyperdriveDb is imported here to make it available for use when the
21	// HTTP adapter migration lands (PR #6/#7). Remove the comment and use it in
22	// the fetch handler once route modules are mounted.
23	// import { createHyperdriveDb } from "../db/hyperdrive.js";
24	
25	// ---------------------------------------------------------------------------
26	// Env — Cloudflare bindings injected at runtime
27	// ---------------------------------------------------------------------------
28	
29	export interface Env {
30	  // Databases
31	  HYPERDRIVE: { connectionString: string };
32	
33	  // Object storage
34	  PAPERCLIP_STORAGE: R2Bucket;
35	
36	  // KV — setup flags, hot config, session cache
37	  PAPERCLIP_KV: KVNamespace;
38	
39	  // Durable Object namespaces
40	  TASK_DO: DurableObjectNamespace;
41	  AGENT_RUN_DO: DurableObjectNamespace;
42	  SCHEDULER_DO: DurableObjectNamespace;
43	
44	  // Queues
45	  PAPERCLIP_QUEUE: Queue;
46	
47	  // Workflows
48	  HEARTBEAT_WORKFLOW: Workflow;
49	  PLUGIN_DISPATCH_WORKFLOW: Workflow;
50	
51	  // Vars (set in wrangler.toml [vars])
52	  DEPLOYMENT_PLATFORM: string;
53	  DEPLOYMENT_MODE: string;
54	  DEPLOYMENT_EXPOSURE: string;
55	
56	  // Secrets (set via `wrangler secret put`)
57	  // MASTER_ENCRYPTION_KEY: string  — encrypts all other secrets stored in DB
58	  // SANDBOX_BRIDGE_URL: string
59	  // SANDBOX_BRIDGE_API_KEY: string
60	
61	  // Sidecar — the Node server running alongside the Workers deployment.
62	  // Workers delegate filesystem, child-process, and plugin-loading operations
63	  // to this process over HTTP (see SidecarClient).
64	  SIDECAR_URL: string;
65	  SIDECAR_API_KEY: string;
66	}
67	
68	// ---------------------------------------------------------------------------
69	// Hono app
70	// ---------------------------------------------------------------------------
71	
72	const app = new Hono<{ Bindings: Env }>();
73	
74	// Health check — always reachable, no auth, no setup gate
75	app.get("/api/health", (c) =>
76	  c.json({
77	    status: "ok",
78	    platform: c.env.DEPLOYMENT_PLATFORM ?? "cloudflare",
79	    mode: c.env.DEPLOYMENT_MODE ?? "authenticated",
80	    ts: new Date().toISOString(),
81	  }),
82	);
83	
84	// First-run setup gate — redirect to /setup until SETUP_COMPLETED is "true"
85	app.use("*", async (c, next) => {
86	  // Allow the setup routes and health check through unconditionally
87	  if (c.req.path === "/api/health" || c.req.path.startsWith("/setup")) {
88	    return next();
89	  }
90	
91	  const setupCompleted = await c.env.PAPERCLIP_KV.get("SETUP_COMPLETED");
92	  if (setupCompleted !== "true") {
93	    return c.redirect("/setup");
94	  }
95	
96	  return next();
97	});
98	
99	// Delegate /setup/* to the setup sub-app.
100	// createSetupApp returns a Hono instance whose routes are relative to "/",
101	// so we strip the "/setup" prefix before forwarding.
102	app.all("/setup/*", async (c) => {
103	  const setupSub = createSetupApp(c.env);
104	  const url = new URL(c.req.url);
105	  // Strip leading "/setup" so routes inside the sub-app match against "/"
106	  url.pathname = url.pathname.replace(/^\/setup/, "") || "/";
107	  const rewritten = new Request(url.toString(), c.req.raw);
108	  return setupSub.fetch(rewritten);
109	});
110	
111	// Exact "/setup" (no trailing slash) — forward as "/"
112	app.all("/setup", async (c) => {
113	  const setupSub = createSetupApp(c.env);
114	  const url = new URL(c.req.url);
115	  url.pathname = "/";
116	  const rewritten = new Request(url.toString(), c.req.raw);
117	  return setupSub.fetch(rewritten);
118	});
119	
120	// ---------------------------------------------------------------------------
121	// API routes
122	// TODO: mount migrated route modules here once the HTTP adapter
123	// migration (PR #6/#7) is complete. Pattern:
124	//
125	//   import { mountRoutes } from "../http/hono-adapter.js";
126	//   import { companyRoutes } from "../../../server/src/routes/companies.js";
127	//   mountRoutes(app, companyRoutes, { db, storage, resolveActor });
128	// ---------------------------------------------------------------------------
129	
130	// Placeholder API fallthrough for any unmounted routes
131	app.all("/api/*", (c) => c.json({ error: "API route not yet mounted in CF Worker" }, 501));
132	
133	// Catch-all for non-API requests — serve the Pages SPA (handled by Cloudflare Pages
134	// when the Worker is linked to a Pages project; this handler is only reached in
135	// local `wrangler dev` mode).
136	app.all("*", (c) =>
137	  c.html(
138	    `<!DOCTYPE html>
139	<html><head><meta charset="UTF-8"><title>Paperclip</title></head>
140	<body>
141	  <p>Loading Paperclip UI... If this persists, the Pages build may not be deployed yet.</p>
142	</body></html>`,
143	  ),
144	);
145	
146	// ---------------------------------------------------------------------------
147	// Default export — Workers fetch handler
148	// ---------------------------------------------------------------------------
149	
150	export default {
151	  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
152	    // Boot the Cloudflare implementations on first request
153	    // (idempotent — registerStorageProvider uses a Map, safe to call multiple times)
154	    bootCloudflare(env);
155	
156	    // ---------------------------------------------------------------------------
157	    // CF service layer — instantiated per-request (Workers are stateless).
158	    //
159	    // SidecarClient delegates Node-only operations (filesystem, child processes,
160	    // plugin loading) to the Paperclip Node server running alongside this Worker.
161	    //
162	    // CfCompanySkillsService stores skill file content in R2 under the key
163	    // pattern `skills/{companyId}/{skillId}/{relativePath}` and falls back to
164	    // the sidecar for local_path / catalog source types.
165	    //
166	    // CfAgentInstructionsService stores per-agent Markdown instruction files in
167	    // R2 under `instructions/{companyId}/{agentId}/{filename}`.
168	    //
169	    // TODO(PR #6/#7): pass these instances into the Hono context (via app.use)
170	    // or directly into route handler factories once route modules are mounted:
171	    //
172	    //   app.use("*", async (c, next) => {
173	    //     c.set("sidecar", sidecar);
174	    //     c.set("skills", skillsService);
175	    //     c.set("instructions", instructionsService);
176	    //     return next();
177	    //   });
178	    // ---------------------------------------------------------------------------
179	    const sidecar = new SidecarClient({
180	      baseUrl: env.SIDECAR_URL,
181	      apiKey: env.SIDECAR_API_KEY,
182	    });
183	    const skillsService = new CfCompanySkillsService(env.PAPERCLIP_STORAGE, sidecar);
184	    const instructionsService = new CfAgentInstructionsService(env.PAPERCLIP_STORAGE);
185	
186	    // Suppress unused-variable warnings until routes are mounted.
187	    void skillsService;
188	    void instructionsService;
189	
190	    return app.fetch(request, env, ctx);
191	  },
192	
193	  // -------------------------------------------------------------------------
194	  // Queues consumer — processes plugin job dispatch messages
195	  // -------------------------------------------------------------------------
196	  async queue(batch: MessageBatch<unknown>, env: Env): Promise<void> {
197	    for (const message of batch.messages) {
198	      const body = message.body as Record<string, unknown>;
199	      const type = body?.type as string | undefined;
200	
201	      if (type === "plugin_job_dispatch") {
202	        const pluginJobId = body.pluginJobId as string;
203	        const pluginSlug = body.pluginSlug as string;
204	        const companyId = body.companyId as string;
205	        const executorMode = (body.executorMode as "sandbox_bridge" | "container") ?? "sandbox_bridge";
206	
207	        try {
208	          await env.PLUGIN_DISPATCH_WORKFLOW.create({
209	            // Use the job ID as the Workflow instance ID for deduplication
210	            id: `plugin-job-${pluginJobId}`,
211	            params: { pluginJobId, pluginSlug, companyId, executorMode },
212	          });
213	          message.ack();
214	        } catch (err) {
215	          // Let the queue retry this message
216	          console.error(
217	            `[Queue] Failed to start PluginDispatchWorkflow for job ${pluginJobId}: ${
218	              err instanceof Error ? err.message : String(err)
219	            }`,
220	          );
221	          message.retry();
222	        }
223	        continue;
224	      }
225	
226	      if (type === "heartbeat_dispatch") {
227	        const agentId = body.agentId as string;
228	        const companyId = body.companyId as string;
229	        const runId = body.runId as string;
230	        const taskId = body.taskId as string | undefined;
231	
232	        try {
233	          await env.HEARTBEAT_WORKFLOW.create({
234	            id: `heartbeat-${runId}`,
235	            params: { agentId, companyId, runId, taskId },
236	          });
237	          message.ack();
238	        } catch (err) {
239	          console.error(
240	            `[Queue] Failed to start HeartbeatWorkflow for run ${runId}: ${
241	              err instanceof Error ? err.message : String(err)
242	            }`,
243	          );
244	          message.retry();
245	        }
246	        continue;
247	      }
248	
249	      // Unknown message type — ack to avoid infinite retries
250	      console.warn(`[Queue] Unknown message type: ${type}`);
251	      message.ack();
252	    }
253	  },
254	
255	  // -------------------------------------------------------------------------
256	  // Cron Triggers — heartbeat sweep, budget checks, DB backup
257	  // -------------------------------------------------------------------------
258	  async scheduled(event: ScheduledEvent, env: Env, _ctx: ExecutionContext): Promise<void> {
259	    const cron = event.cron;
260	    console.log(`[Cron] Firing cron: ${cron}`);
261	
262	    // TODO: replace with calls to the scheduler DO or direct internal API
263	    // endpoints once the HTTP adapter migration lands.
264	    if (cron === "*/5 * * * *") {
265	      // Heartbeat sweep — find agents that are due and enqueue heartbeat jobs
266	      // TODO: implement by querying the DB for due agents and posting to PAPERCLIP_QUEUE
267	      console.log("[Cron] Heartbeat sweep — not yet implemented");
268	    } else if (cron === "0 * * * *") {
269	      // Budget threshold check
270	      // TODO: implement by calling the internal budget service endpoint
271	      console.log("[Cron] Budget check — not yet implemented");
272	    } else if (cron === "0 3 * * *") {
273	      // Daily DB backup to R2
274	      // TODO: implement by triggering a Workflow that dumps Postgres to R2
275	      console.log("[Cron] DB backup — not yet implemented");
276	    }
277	  },
278	};
279	
280	// ---------------------------------------------------------------------------
281	// Named Durable Object + Workflow exports
282	//
283	// Wrangler requires that DO classes and Workflow classes be named exports from
284	// the Worker's main module (the file pointed to by `main` in wrangler.toml).
285	// ---------------------------------------------------------------------------
286	
287	export { TaskDO } from "../runtime/task-do.js";
288	export { AgentRunDO } from "../runtime/agent-run-do.js";
289	export { SchedulerDO } from "../scheduler/scheduler-do.js";
290	export { HeartbeatWorkflow } from "../runtime/workflows/heartbeat.js";
291	export { PluginDispatchWorkflow } from "../runtime/workflows/plugin-dispatch.js";
